"use client";

import * as React from "react";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { fieldOpen, formFieldBase, formFieldSingleLine } from "./_shared";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "./command";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";

const finishes = [
  { value: "copper", label: "Copper" },
  { value: "bronze", label: "Bronze" },
  { value: "brass", label: "Brass" },
  { value: "pewter", label: "Pewter" },
  { value: "graphite", label: "Graphite" },
];

/**
 * Burnished combobox: a graphite bevel field that opens a searchable list on
 * the raised umber panel, as wide as the field. The chosen row carries a
 * copper tick.
 */
export function ComboboxDemo() {
  const [open, setOpen] = React.useState(false);
  const [value, setValue] = React.useState("");
  const selected = finishes.find((finish) => finish.value === value);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        role="combobox"
        aria-expanded={open}
        data-slot="combobox-trigger"
        className={cn(
          formFieldBase,
          formFieldSingleLine,
          "w-60 cursor-default items-center justify-between gap-2 text-start",
          fieldOpen,
          !selected && "text-muted-foreground",
        )}
      >
        <span className="truncate">{selected ? selected.label : "Select a finish"}</span>
        <Icon
          icon="ph:caret-up-down"
          className="size-4 shrink-0 text-muted-foreground"
          aria-hidden="true"
        />
      </PopoverTrigger>
      <PopoverContent align="start" className="w-(--anchor-width) gap-0 p-0">
        <Command className="bg-transparent shadow-none">
          <CommandInput placeholder="Search finishes" />
          <CommandList>
            <CommandEmpty>No finish found.</CommandEmpty>
            <CommandGroup>
              {finishes.map((finish) => (
                <CommandItem
                  key={finish.value}
                  value={finish.value}
                  onSelect={(currentValue: string) => {
                    setValue(currentValue === value ? "" : currentValue);
                    setOpen(false);
                  }}
                >
                  {finish.label}
                  <Icon
                    icon="ph:check-bold"
                    className={cn(
                      "ms-auto size-4 text-primary-text",
                      value === finish.value ? "opacity-100" : "opacity-0",
                    )}
                    aria-hidden="true"
                  />
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}
